#!/bin/sh
# Builds the Settings preview shader from window-open.glsl, so both show the same animations.
# Needs qsb (qt6-shadertools): QSB=/path/to/qsb sh build-preview.sh
set -e
here=$(dirname "$0")
out="$here/../../quickshell/falcon/shaders"
{
    cat <<'HEAD'
#version 440
// Generated by config/niri/shaders/build-preview.sh from config/niri/shaders/window-open.glsl.
// Do not edit: change that file and run the script, which also writes winopen.frag.qsb.
// The ShaderEffect covers a piece of desktop; `area` is the window's place in it
// (x, y, width, height as fractions), `size` the window in pixels, `effect` its number.

layout(location = 0) in vec2 qt_TexCoord0;
layout(location = 0) out vec4 fragColor;

layout(std140, binding = 0) uniform buf {
    mat4 qt_Matrix;
    float qt_Opacity;
    float niri_clamped_progress;
    float niri_random_seed;
    float effect;
    vec4 area;
    vec2 size;
};

layout(binding = 1) uniform sampler2D niri_tex;

#define texture2D texture
const mat3 niri_geo_to_tex = mat3(1.0);

HEAD
    cat "$here/window-open.glsl"
    cat <<'TAIL'

void main() {
    vec2 g = (qt_TexCoord0 - area.xy) / area.zw;
    fragColor = fo_pick(effect, g, size, niri_clamped_progress) * qt_Opacity;
}
TAIL
} >"$out/winopen.frag"
"${QSB:-qsb}" --glsl "100 es,120,150" --hlsl 50 --msl 12 -o "$out/winopen.frag.qsb" "$out/winopen.frag"
